import { fileLetter } from '../chess/boardSpec';
import type { Color } from '../chess/fen';
import { type Affinity, PIECE_NAME, type PieceType } from '../rules/pieces';

// Piece art: one drawing per piece type in a sprite (src/assets/pieces.svg, generated by
// scripts/make-pieces.mjs), coloured by CSS variables (.piece-w / .piece-b in style.css).
import sprite from '../assets/pieces.svg?raw';

const SVG_NS = 'http://www.w3.org/2000/svg';

/** Puts the sprite into the page once, so pieces can <use> its symbols. */
function ensureSprite(): void {
  if (document.getElementById('piece-sprite')) return;
  const holder = document.createElement('div');
  holder.id = 'piece-sprite';
  holder.setAttribute('aria-hidden', 'true');
  holder.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden';
  holder.innerHTML = sprite;
  document.body.prepend(holder);
}

/** Whether the sprite has art for this piece type. */
export function hasPieceArt(type: PieceType): boolean {
  return sprite.includes(`id="piece-${type}"`);
}

/**
 * Colours passed in here are sides in the game's FEN: 'w' is always the player, 'b' the opponent.
 * When the player plays Black this round, the art is swapped so their pieces look black.
 */
let playerColor: Color = 'w';

export function setPlayerColor(color: Color): void {
  playerColor = color;
}

/** The colour a side's pieces are drawn in. */
export function displayColor(side: Color): Color {
  if (playerColor === 'w') return side;
  return side === 'w' ? 'b' : 'w';
}

/**
 * A piece's image: an <svg> showing its sprite symbol in its side's colours. `name` is what screen
 * readers (and tests) see; empty for decoration.
 */
export function pieceSvg(
  type: PieceType,
  color: Color = 'w',
  name: string = PIECE_NAME[type],
  className = '',
): SVGSVGElement {
  ensureSprite();
  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('class', `piece-art piece-${displayColor(color)}${className ? ` ${className}` : ''}`);
  svg.setAttribute('viewBox', '0 0 100 100');
  if (name) {
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', name);
  } else {
    svg.setAttribute('aria-hidden', 'true');
  }
  const use = document.createElementNS(SVG_NS, 'use');
  use.setAttribute('href', `#piece-${type}`);
  svg.append(use);
  return svg;
}

/** Shows another piece in an image made by pieceSvg (keeping its colour). */
export function setPieceType(svg: SVGSVGElement, type: PieceType): void {
  svg.querySelector('use')?.setAttribute('href', `#piece-${type}`);
}

/**
 * Puts the piece's image inside `el` (a board square's piece element, or the drag ghost). An
 * affinity pawn gets a small badge of the piece it merges toward.
 */
export function fillPiece(el: HTMLElement, type: PieceType, color: Color = 'w', affinity?: Affinity): void {
  const img = pieceSvg(type, color, affinity ? `${PIECE_NAME[affinity]}-pawn` : PIECE_NAME[type]);
  if (!affinity) {
    el.replaceChildren(img);
    return;
  }
  el.replaceChildren(img, pieceSvg(affinity, color, '', 'affinity-badge'));
}

/** A small inline piece image as HTML, for text such as the opponent's piece list (with an affinity badge). */
export function inlinePiece(type: PieceType, color: Color = 'w', affinity?: Affinity): string {
  ensureSprite();
  const svg = (t: PieceType, className: string, name: string) =>
    `<svg class="${className} piece-art piece-${displayColor(color)}" viewBox="0 0 100 100" ${
      name ? `role="img" aria-label="${name}"` : 'aria-hidden="true"'
    }><use href="#piece-${t}"/></svg>`;
  const img = svg(type, 'inline-piece', affinity ? `${PIECE_NAME[affinity]}-pawn` : PIECE_NAME[type]);
  if (!affinity) return img;
  return `<span class="inline-affinity">${img}${svg(affinity, 'affinity-badge', '')}</span>`;
}

export function label(className: string, text: string): HTMLElement {
  const el = document.createElement('span');
  el.className = className;
  el.textContent = text;
  return el;
}

/** A board square with colour, data-file/data-rank and edge coordinate labels. Rank 0 is drawn at the bottom. */
export function squareEl(file: number, rank: number): HTMLElement {
  const cell = document.createElement('div');
  cell.className = `square ${(file + rank) % 2 === 0 ? 'dark' : 'light'}`;
  cell.dataset.file = String(file);
  cell.dataset.rank = String(rank);
  if (file === 0) cell.appendChild(label('rank-label', String(rank + 1)));
  if (rank === 0) cell.appendChild(label('file-label', fileLetter(file)));
  return cell;
}
